/**
 * Generator wiring for the commerce layer.
 *
 * The store runtime needs to know which generated file holds each shop page so
 * cart links, the product page and the COD confirmation resolve on every
 * runtime (.php, .html, /slug/). One resolver, three generators - so a link
 * cannot point at the wrong file in one export and the right one in another.
 */

import type { SiteModel } from '../types';
import { pageFileSlug, siteContentPages } from './siteRenderer';
import { COD_STATUSES, DEFAULT_SETTINGS, seedJSON } from './commerceData';

export type ShopPathKind = 'php' | 'node' | 'wordpress';

export interface ShopPaths {
  product: string;
  shop: string;
  checkout: string;
  confirmation: string;
  track: string;
  api: string;
}

const SLUG_BY_PURPOSE: Record<string, string[]> = {
  product: ['product', 'shop-product', 'item'],
  shop: ['shop', 'products', 'store', 'catalog'],
  checkout: ['checkout', 'cart-checkout', 'order'],
  confirmation: ['order-confirmation', 'confirmation', 'thank-you', 'order-complete'],
  track: ['track-order', 'track', 'order-tracking'],
};

function fileFor(
  site: SiteModel,
  kind: ShopPathKind,
  purposes: string[]
): string {
  const pages = siteContentPages(site);
  for (const purpose of purposes) {
    const hit = pages.find((p) => p.config?.slug === purpose || p.id === purpose);
    if (hit) return urlFor(hit, kind);
  }
  // Nothing matched: fall back to the first page whose name mentions the purpose.
  for (const purpose of purposes) {
    const hit = pages.find((p) => String(p.name || '').toLowerCase().includes(purpose));
    if (hit) return urlFor(hit, kind);
  }
  const home = pages[0];
  return home ? urlFor(home, kind) : kind === 'wordpress' ? '/' : 'index.html';
}

export function urlFor(
  page: { id: string; config: PageConfigLike },
  kind: ShopPathKind
): string {
  const slug = pageFileSlug(page as any);
  if (kind === 'php') return `${slug}.php`;
  if (kind === 'node') return `${slug}.html`;
  return `/${slug}/`;
}

interface PageConfigLike {
  slug?: string;
}

/** Resolve every path the store runtime needs, for one export flavour. */
export function shopPaths(site: SiteModel, kind: ShopPathKind = 'php'): ShopPaths {
  return {
    product: fileFor(site, kind, SLUG_BY_PURPOSE.product),
    shop: fileFor(site, kind, SLUG_BY_PURPOSE.shop),
    checkout: fileFor(site, kind, SLUG_BY_PURPOSE.checkout),
    confirmation: fileFor(site, kind, SLUG_BY_PURPOSE.confirmation),
    track: fileFor(site, kind, SLUG_BY_PURPOSE.track),
    api: kind === 'wordpress' ? '/?wc_shop_api=1' : '/api/shop',
  };
}

/**
 * PHP seed file. A nowdoc keeps the JSON byte-for-byte, so no escaping bug can
 * ever corrupt the catalog.
 */
export function shopSeedFile(): string {
  return `<?php
/**
 * Seed catalog for the store. Written once, read on first request.
 * Generated by WebCraft Pro - safe to delete to reset the store.
 */
return json_decode(<<<'WEBCRAFT_SEED'
${seedJSON()}
WEBCRAFT_SEED
, true);
`;
}

/** The same seed as a Node JSON module. */
export function shopSeedJson(): string {
  return `${seedJSON()}\n`;
}

/** The client bootstrap the browser needs before `script.js` runs. */
export function clientSeedScript(paths: ShopPaths, kind: ShopPathKind): string {
  const api = kind === 'wordpress' ? '/?wc_shop_api=1' : '/api/shop';
  return (
    'window.__WB_SHOP__ = Object.assign({}, window.__WB_SHOP__ || {}, ' +
    JSON.stringify({
      productPath: paths.product,
      shopPath: paths.shop,
      checkoutPath: paths.checkout,
      confirmationPath: paths.confirmation,
      trackPath: paths.track,
      codStatuses: COD_STATUSES,
      settings: DEFAULT_SETTINGS,
      api,
    }) +
    ');'
  );
}